178	// ListTemporary lists all shadow branches with their checkpoint info.
179	func (s *GitStore) ListTemporary(ctx context.Context) ([]TemporaryInfo, error) {
180		if err := ctx.Err(); err != nil {
181			return nil, err //nolint:wrapcheck // Propagating context cancellation
182		}
183	
184		iter, err := s.repo.Branches()
185		if err != nil {
186			return nil, fmt.Errorf("failed to list branches: %w", err)
187		}
188	
189		var results []TemporaryInfo
190		err = iter.ForEach(func(ref *plumbing.Reference) error {
191			if err := ctx.Err(); err != nil {
192				return err //nolint:wrapcheck // Propagating context cancellation
193			}
194			branchName := ref.Name().Short()
195			if !strings.HasPrefix(branchName, ShadowBranchPrefix) {
196				return nil
197			}
198	
199			// Skip the sessions branch
200			if branchName == paths.MetadataBranchName {
201				return nil
202			}
203	
204			commit, commitErr := s.repo.CommitObject(ref.Hash())
205			if commitErr != nil {
206				//nolint:nilerr // Skip branches we can't read (non-fatal)
207				return nil
208			}
209	
210			sessionID, _ := trailers.ParseSession(commit.Message)
211	
212			// Extract base commit from branch name (handles new "entire/<commit>-<worktreeHash>" format)
213			baseCommit, _, _ := ParseShadowBranchName(branchName)
214	
215			results = append(results, TemporaryInfo{
216				BranchName:   branchName,
217				BaseCommit:   baseCommit,
218				LatestCommit: ref.Hash(),
219				SessionID:    sessionID,
220				Timestamp:    commit.Author.When,
221			})
222	
